class MajorityElement {
  constructor() {
    this.count = 0;
    this.candidate = null;
  }
  update(n) {
    if (this.count === 0) {
      this.candidate = n;
    } else if (this.count === 1) {
      this.candidate = null;
    } else if (this.count === -1) {
      this.count = 0;
    }
    this.count += n === this.candidate ? 1 : -1;
  }
  get() {
    return this.candidate;
  }
}
